export const APP_SDK_FILES: Record<string, string> = {
  "src/bridge.ts": "/**\n * EL PUENTE: la pantalla vive en un iframe con origen nulo y no puede llamar a\n * la API. Cada operación viaja por `postMessage` al host (Cortex), que la\n * reenvía al servidor con la sesión y el rol de quien mira. Aquí no se decide\n * ningún permiso: lo decide el servidor.\n *\n * Mensaje de ida:    { cortex: 1, id, op, args }\n * Mensaje de vuelta: { cortex: 1, id, ok: true, data } | { cortex: 1, id, ok: false, error }\n *\n * Respuesta en dos tiempos (opcional, `upd: true` en el mensaje de ida): el host puede contestar\n * al instante con lo que tiene guardado y, si al refrescar el dato cambió, mandar después\n *   { cortex: 1, update: true, id, data }\n * con el mismo id. `call()` resuelve con la primera respuesta; la segunda se entrega a quien\n * se registró con `withUpdates` (los ganchos de React la usan para volver a pintar).\n * Un host viejo ignora `upd` y un SDK viejo ignora los `update`: nada se rompe.\n */\n\nimport { handleHostEvent, resetEvents } from './events';\n\n/** Cuánto se espera la respuesta del host antes de rendirse. */\nexport const BRIDGE_TIMEOUT_MS = 30_000;\n\ninterface Pending {\n  resolve: (data: unknown) => void;\n  reject: (err: Error) => void;\n  timer: ReturnType<typeof setTimeout>;\n}\n\nconst pending = new Map<string, Pending>();\n/** Quién espera la segunda respuesta de una llamada, hasta que llegue o venza. */\nconst updaters = new Map<string, { fn: () => void; timer: ReturnType<typeof setTimeout> }>();\n/** El oyente de actualizaciones vigente mientras se emiten llamadas (ver `withUpdates`). */\nlet scope: (() => void) | null = null;\nlet seq = 0;\nlet listening = false;\n\nfunction onMessage(event: MessageEvent): void {\n  // Solo se le cree al host (la ventana que contiene este iframe).\n  if (event.source !== window.parent) return;\n  const msg = event.data as\n    | {\n        cortex?: number;\n        id?: string;\n        ok?: boolean;\n        update?: boolean;\n        data?: unknown;\n        error?: string;\n      }\n    | null\n    | undefined;\n  if (!msg || msg.cortex !== 1) return;\n  // Avisos del host sin llamada de por medio (canal en vivo, cola sin señal, visibilidad).\n  if (typeof (msg as { event?: unknown }).event === 'string') {\n    handleHostEvent(msg as Record<string, unknown>);\n    return;\n  }\n  if (typeof msg.id !== 'string') return;\n  if (msg.update === true) {\n    // La segunda respuesta de una llamada ya resuelta: se avisa una sola vez.\n    const u = updaters.get(msg.id);\n    if (!u) return;\n    updaters.delete(msg.id);\n    clearTimeout(u.timer);\n    u.fn();\n    return;\n  }\n  const p = pending.get(msg.id);\n  if (!p) return;\n  pending.delete(msg.id);\n  clearTimeout(p.timer);\n  if (msg.ok) p.resolve(msg.data);\n  else p.reject(new Error(msg.error || 'No se pudo completar la operación.'));\n}\n\nexport function listen(): void {\n  if (listening) return;\n  window.addEventListener('message', onMessage);\n  listening = true;\n}\n\n/** Operaciones lentas (leer un documento con el modelo): esperan más. */\nexport const SLOW_BRIDGE_TIMEOUT_MS = 75_000;\n\n/**\n * Mientras corre `fn` (de forma síncrona), las llamadas que emita piden respuesta en dos tiempos y\n * `onUpdate` se invoca cuando el host manda el dato fresco. Las llamadas que `fn` haga después de\n * un `await` no quedan cubiertas (siguen funcionando, sin aviso).\n */\nexport function withUpdates<T>(onUpdate: () => void, fn: () => T): T {\n  const prev = scope;\n  scope = onUpdate;\n  try {\n    return fn();\n  } finally {\n    scope = prev;\n  }\n}\n\n/** Llama una operación del host y espera su respuesta. `timeoutMs` alarga la espera de las lentas. */\nexport function call<T = unknown>(\n  op: string,\n  args?: unknown,\n  opts: { timeoutMs?: number } = {},\n): Promise<T> {\n  if (typeof window === 'undefined' || window.parent === window) {\n    return Promise.reject(new Error('Esta pantalla solo funciona dentro de la aplicación.'));\n  }\n  listen();\n  const id = `${Date.now().toString(36)}-${++seq}`;\n  const onUpdate = scope;\n  return new Promise<T>((resolve, reject) => {\n    const timer = setTimeout(() => {\n      pending.delete(id);\n      reject(new Error('La operación tardó demasiado. Intenta de nuevo.'));\n    }, opts.timeoutMs ?? BRIDGE_TIMEOUT_MS);\n    pending.set(id, {\n      resolve: (d) => {\n        if (onUpdate) {\n          // Espera la segunda respuesta un rato; después se olvida.\n          const t = setTimeout(() => updaters.delete(id), BRIDGE_TIMEOUT_MS);\n          updaters.set(id, { fn: onUpdate, timer: t });\n        }\n        (resolve as (d: unknown) => void)(d);\n      },\n      reject,\n      timer,\n    });\n    // El origen del host no se conoce desde un iframe sin origen: '*' es necesario.\n    window.parent.postMessage(\n      { cortex: 1, id, op, args: args ?? null, ...(onUpdate ? { upd: true } : {}) },\n      '*',\n    );\n  });\n}\n\n/** Solo para pruebas: olvida lo pendiente y quita el oyente. */\nexport function resetBridge(): void {\n  for (const p of pending.values()) clearTimeout(p.timer);\n  pending.clear();\n  for (const u of updaters.values()) clearTimeout(u.timer);\n  updaters.clear();\n  scope = null;\n  if (listening && typeof window !== 'undefined') window.removeEventListener('message', onMessage);\n  listening = false;\n  seq = 0;\n  resetEvents();\n}\n",
  "src/cortex.ts": "import { SLOW_BRIDGE_TIMEOUT_MS, call, listen } from './bridge';\nimport { addLiveSub, getLiveStatus, getOutbox, liveUnion, setLiveStatus } from './events';\nimport type {\n  ActionResult,\n  ConfirmOptions,\n  LiveEvent,\n  LiveStatus,\n  MaybeQueued,\n  OutboxItem,\n  PickOptions,\n  PrintOptions,\n  QueryOptions,\n  ScanOptions,\n  ScanResult,\n  SdkAction,\n  SdkField,\n  SdkGeofence,\n  SdkLocation,\n  SdkPerson,\n  SdkPosition,\n  SdkRow,\n  SdkTable,\n  SdkUser,\n  UploadOptions,\n  UploadResult,\n  WriteOptions,\n} from './types';\n\n/** Avisa al host qué tablas miran las pantallas (la unión); él abre UN canal por app. */\nlet syncScheduled = false;\nfunction syncLive(): void {\n  if (syncScheduled) return;\n  syncScheduled = true;\n  void Promise.resolve().then(async () => {\n    syncScheduled = false;\n    try {\n      listen();\n      const res = await call<{ status?: LiveStatus } | null>('live.set', { tables: liveUnion() });\n      if (res?.status) setLiveStatus(res.status);\n    } catch {\n      // Un host que no tiene canal en vivo: la pantalla se queda sondeando.\n      setLiveStatus('off');\n    }\n  });\n}\n\n/**\n * `cortex`: todas las operaciones como promesas. Se agrupan igual que en el\n * servidor (`tables.query` ↔ op `tables.query`). Las de `nav` y `ui` las\n * resuelve el propio host sin ir al servidor.\n */\nexport const cortex = {\n  user: {\n    /** Quién está usando la pantalla, con su rol y atributos. */\n    me: () => call<SdkUser>('user.me'),\n  },\n  people: {\n    /**\n     * A quién se le puede asignar algo: usuarios de la app y miembros con rol, con su `ref`.\n     * Solo si el rol de quien mira asigna tareas (si no, error). `roles` limita por rol.\n     */\n    list: (opts: { roles?: string[] } = {}) => call<SdkPerson[]>('people.list', opts),\n  },\n  tables: {\n    /** Las tablas que el rol puede leer, con sus campos. */\n    list: () => call<SdkTable[]>('tables.list'),\n    query: (table: string, opts: QueryOptions = {}) =>\n      call<{ rows: SdkRow[]; fields?: SdkField[]; total?: number }>('tables.query', {\n        table,\n        ...opts,\n      }),\n    get: (table: string, id: string) => call<SdkRow>('tables.get', { table, id }),\n    /**\n     * Crea una fila. Con `{ offline: true }`, sin señal se guarda en el teléfono y contesta\n     * `{ queued: true, localId }`; el `localId` vale como `id` en `update`/`action`/`files.upload`\n     * encolados después (se cambia por el real al enviar).\n     */\n    insert: <O extends WriteOptions | undefined = undefined>(\n      table: string,\n      values: Record<string, unknown>,\n      opts?: O,\n    ) =>\n      call<MaybeQueued<SdkRow, O>>('tables.insert', {\n        table,\n        values,\n        ...(opts?.offline ? { offline: true } : {}),\n      }),\n    update: <O extends WriteOptions | undefined = undefined>(\n      table: string,\n      id: string,\n      values: Record<string, unknown>,\n      opts?: O,\n    ) =>\n      call<MaybeQueued<SdkRow, O>>('tables.update', {\n        table,\n        id,\n        values,\n        ...(opts?.offline ? { offline: true } : {}),\n      }),\n    /**\n     * Corre el botón de flujo con esa clave (`'tomar'`, `'cerrar'`, `'aprobar'`, `'rechazar'`…)\n     * sobre una fila, igual que en las pantallas de bloques: mismo rol, mismos efectos y\n     * mismas reglas. `reason` es el motivo (por ejemplo al rechazar).\n     */\n    action: <O extends (WriteOptions & { reason?: string }) | undefined = undefined>(\n      table: string,\n      id: string,\n      action: string,\n      opts?: O,\n    ) =>\n      call<MaybeQueued<ActionResult, O>>('tables.action', {\n        table,\n        id,\n        action,\n        reason: opts?.reason,\n        ...(opts?.offline ? { offline: true } : {}),\n      }),\n    /** Los botones de flujo de la tabla que el rol puede correr. */\n    listActions: (table: string) => call<SdkAction[]>('tables.listActions', { table }),\n  },\n  files: {\n    /**\n     * Sube un archivo y lo AGREGA al campo de archivos de esa fila (respeta quién puede editar\n     * ese campo). Las fotos se comprimen antes de subir. Pesa hasta 4 MB ya comprimido.\n     */\n    upload: <O extends UploadOptions>(file: File | Blob, opts: O) =>\n      call<MaybeQueued<UploadResult, O>>(\n        'files.upload',\n        { ...opts, file },\n        { timeoutMs: SLOW_BRIDGE_TIMEOUT_MS },\n      ),\n    /**\n     * Abre el selector de archivos o la cámara y devuelve lo elegido (`[]` si se cancela).\n     * Solo funciona dentro del navegador, y desde un toque de la persona (un botón).\n     */\n    pick: (opts: PickOptions = {}) => pickFiles(opts),\n  },\n  docs: {\n    /**\n     * Lee una foto o PDF (hasta 4 MB) con visión: devuelve los datos del encabezado y, si se\n     * pide, un arreglo de renglones. Nada se guarda: la pantalla decide qué hacer con lo leído.\n     */\n    scan: (file: File | Blob, opts: ScanOptions = {}) =>\n      call<ScanResult>('docs.scan', { ...opts, file }, { timeoutMs: SLOW_BRIDGE_TIMEOUT_MS }),\n  },\n  voice: {\n    /** Pasa una grabación de voz a texto. */\n    transcribe: (audio: Blob) =>\n      call<{ text: string }>('voice.transcribe', { audio }, { timeoutMs: SLOW_BRIDGE_TIMEOUT_MS }),\n  },\n  location: {\n    /**\n     * La posición de quien usa la pantalla, con la zona de la app donde está. `null` si no hay\n     * señal, no dio permiso o no aceptó compartir ubicación. La pide el marco de Cortex.\n     */\n    current: () => call<SdkPosition | null>('location.current'),\n  },\n  locations: {\n    /** Última ubicación de cada persona (solo si el rol puede verlas). */\n    live: () => call<SdkLocation[]>('locations.live'),\n  },\n  geofences: {\n    list: () => call<SdkGeofence[]>('geofences.list'),\n  },\n  ai: {\n    /** Pregunta corta al modelo rápido, con datos opcionales. Devuelve texto. */\n    ask: (prompt: string, data?: unknown) => call<string>('ai.ask', { prompt, data }),\n  },\n  functions: {\n    /** Función de servidor de la app (fase 2). */\n    call: <T = unknown>(name: string, input?: unknown) =>\n      call<T>('functions.call', { name, input }),\n  },\n  db: {\n    /** SQL sobre la base propia de la app (fase 3). */\n    query: <T = Record<string, unknown>>(sql: string, params: unknown[] = []) =>\n      call<{ rows: T[] }>('db.query', { sql, params }),\n  },\n  live: {\n    /**\n     * Avisa cuando cambia una de estas tablas (las filas que el rol ve). Devuelve cómo dejar de\n     * escuchar. El canal lo abre el marco; sin canal (`status() === 'off'`) no llega nada y\n     * conviene sondear. `useQuery(..., { live: true })` ya lo hace por ti.\n     */\n    subscribe: (tables: string[], cb: (ev: LiveEvent) => void): (() => void) => {\n      listen();\n      const off = addLiveSub(tables, cb);\n      syncLive();\n      return () => {\n        off();\n        syncLive();\n      };\n    },\n    /** `live` conectado · `reconnecting` reintentando · `off` sin canal. */\n    status: (): LiveStatus => getLiveStatus(),\n  },\n  outbox: {\n    /** Lo que espera señal en el teléfono (operaciones hechas con `{ offline: true }`). */\n    list: async (): Promise<OutboxItem[]> => {\n      try {\n        listen();\n        const res = await call<{ items?: OutboxItem[] } | null>('outbox.list');\n        return res?.items ?? getOutbox().items;\n      } catch {\n        return getOutbox().items;\n      }\n    },\n    /** Reintenta ahora lo que está en espera o rechazado. */\n    retry: () => call<void>('outbox.retry'),\n    /** Quita una operación de la cola (y su archivo guardado). */\n    discard: (localId: string) => call<void>('outbox.discard', { localId }),\n  },\n  nav: {\n    /** Abre otra pantalla de la app, con campos prellenados si se quiere. */\n    go: (target: { screen: string; prefill?: Record<string, string | number> }) =>\n      call<void>('nav.go', target),\n  },\n  ui: {\n    /** Muestra un aviso breve arriba del marco de la app. */\n    toast: (text: string) => call<void>('ui.toast', { text }),\n    /** Descarga un archivo (el marco lo hace: la pantalla no puede). `data` es un Blob o texto. */\n    download: (filename: string, data: Blob | string, mime?: string) =>\n      call<void>('ui.download', { filename, data, mime }),\n    /** Pregunta «¿seguro?» con el diálogo de Cortex. `true` si la persona confirma. */\n    confirm: (text: string, opts: ConfirmOptions = {}) =>\n      call<boolean>('ui.confirm', { text, ...opts }),\n    /**\n     * Imprime un HTML con el diálogo de impresión del navegador (el marco lo hace: la pantalla\n     * no puede). El HTML se sanea (sin scripts) y se imprime aparte, sin tocar la pantalla.\n     */\n    print: (html: string, opts: PrintOptions = {}) =>\n      call<void>('ui.print', { html, title: opts.title }),\n  },\n};\n\n/** El selector de archivos de la propia pantalla (un `<input type=file>` que no se ve). */\nfunction pickFiles(opts: PickOptions): Promise<File[]> {\n  if (typeof document === 'undefined')\n    return Promise.reject(new Error('El selector de archivos solo funciona en el navegador.'));\n  return new Promise<File[]>((resolve) => {\n    const input = document.createElement('input');\n    input.type = 'file';\n    if (opts.accept) input.accept = opts.accept;\n    if (opts.capture) input.setAttribute('capture', opts.capture);\n    if (opts.multiple) input.multiple = true;\n    input.style.position = 'fixed';\n    input.style.left = '-9999px';\n    let settled = false;\n    const done = (files: File[]) => {\n      if (settled) return;\n      settled = true;\n      input.remove();\n      resolve(files);\n    };\n    input.addEventListener('change', () => done(Array.from(input.files ?? [])));\n    input.addEventListener('cancel', () => done([]));\n    document.body.appendChild(input);\n    input.click();\n  });\n}\n",
  "src/events.ts": "import type { LiveEvent, LiveStatus, OutboxState } from './types';\n\n/**\n * LO QUE EL HOST EMPUJA AL IFRAME sin que la pantalla lo pida:\n *\n *   { cortex: 1, event: 'changed',     table, at }   cambió una tabla (canal en vivo)\n *   { cortex: 1, event: 'live-status', status }      `live` | `reconnecting` | `off`\n *   { cortex: 1, event: 'outbox',      state }       la cola sin señal cambió\n *   { cortex: 1, event: 'visible',     visible }     la pantalla se muestra / se oculta (iframes vivos)\n *\n * Aquí vive el estado que esos mensajes alimentan; los ganchos y `cortex.live` / `cortex.outbox`\n * leen de aquí. No importa nada del puente (el puente es quien llama a `handleHostEvent`).\n */\n\nexport const EMPTY_OUTBOX: OutboxState = { items: [], pending: 0, failed: 0, online: true };\n\ninterface LiveSub {\n  tables: Set<string>;\n  cb: (ev: LiveEvent) => void;\n}\n\nconst liveSubs = new Set<LiveSub>();\nconst statusListeners = new Set<(s: LiveStatus) => void>();\nconst visibleListeners = new Set<(v: boolean) => void>();\nconst outboxListeners = new Set<(s: OutboxState) => void>();\nlet liveStatus: LiveStatus = 'off';\nlet hostVisible = true;\nlet outbox: OutboxState = EMPTY_OUTBOX;\n\nexport function getLiveStatus(): LiveStatus {\n  return liveStatus;\n}\n\nexport function setLiveStatus(next: LiveStatus): void {\n  if (next === liveStatus) return;\n  liveStatus = next;\n  for (const fn of [...statusListeners]) fn(next);\n}\n\nexport function onLiveStatus(fn: (s: LiveStatus) => void): () => void {\n  statusListeners.add(fn);\n  return () => statusListeners.delete(fn);\n}\n\n/** Registra una suscripción; devuelve cómo quitarla. */\nexport function addLiveSub(tables: string[], cb: (ev: LiveEvent) => void): () => void {\n  const sub: LiveSub = { tables: new Set(tables), cb };\n  liveSubs.add(sub);\n  return () => liveSubs.delete(sub);\n}\n\n/** La unión de las tablas que alguien está mirando (lo que se le pide al host). */\nexport function liveUnion(): string[] {\n  const all = new Set<string>();\n  for (const s of liveSubs) for (const t of s.tables) all.add(t);\n  return [...all].sort();\n}\n\nfunction emitChanged(ev: LiveEvent): void {\n  for (const s of [...liveSubs]) {\n    if (!s.tables.has(ev.table)) continue;\n    try {\n      s.cb(ev);\n    } catch {\n      // Un oyente que falla no debe tumbar a los demás.\n    }\n  }\n}\n\n/** ¿El host muestra esta pantalla? (iframes vivos: una oculta no sondea). */\nexport function isHostVisible(): boolean {\n  return hostVisible;\n}\n\nexport function onHostVisible(fn: (v: boolean) => void): () => void {\n  visibleListeners.add(fn);\n  return () => visibleListeners.delete(fn);\n}\n\nexport function getOutbox(): OutboxState {\n  return outbox;\n}\n\nexport function onOutbox(fn: (s: OutboxState) => void): () => void {\n  outboxListeners.add(fn);\n  return () => outboxListeners.delete(fn);\n}\n\nconst STATUSES: LiveStatus[] = ['live', 'reconnecting', 'off'];\n\n/** Atiende un mensaje del host que no es respuesta a una llamada. */\nexport function handleHostEvent(msg: Record<string, unknown>): void {\n  switch (msg.event) {\n    case 'changed':\n      if (typeof msg.table === 'string')\n        emitChanged({ table: msg.table, at: typeof msg.at === 'string' ? msg.at : '' });\n      return;\n    case 'live-status':\n      if (STATUSES.includes(msg.status as LiveStatus)) setLiveStatus(msg.status as LiveStatus);\n      return;\n    case 'outbox':\n      if (msg.state && typeof msg.state === 'object') {\n        outbox = msg.state as OutboxState;\n        for (const fn of [...outboxListeners]) fn(outbox);\n      }\n      return;\n    case 'visible': {\n      const v = msg.visible !== false;\n      if (v === hostVisible) return;\n      hostVisible = v;\n      for (const fn of [...visibleListeners]) fn(v);\n      return;\n    }\n  }\n}\n\n/** Solo para pruebas. */\nexport function resetEvents(): void {\n  liveSubs.clear();\n  statusListeners.clear();\n  visibleListeners.clear();\n  outboxListeners.clear();\n  liveStatus = 'off';\n  hostVisible = true;\n  outbox = EMPTY_OUTBOX;\n}\n",
  "src/index.ts": "/**\n * @cortex/app-sdk — lo que una pantalla con código usa para hablar con Cortex.\n * Todo viaja por el puente (postMessage); el servidor aplica el rol.\n */\nexport { cortex } from './cortex';\nexport { call, withUpdates, BRIDGE_TIMEOUT_MS, SLOW_BRIDGE_TIMEOUT_MS } from './bridge';\nexport {\n  useAsync,\n  useLive,\n  useLiveStatus,\n  useLocations,\n  useOutbox,\n  useQuery,\n  useUser,\n} from './react';\nexport type {\n  ActionResult,\n  ConfirmOptions,\n  LiveEvent,\n  LiveOptions,\n  LiveStatus,\n  MaybeQueued,\n  OutboxItem,\n  OutboxState,\n  Queued,\n  WriteOptions,\n  PrintOptions,\n  PickOptions,\n  ScanOptions,\n  ScanResult,\n  SdkAction,\n  SdkPosition,\n  UploadOptions,\n  UploadResult,\n  QueryOptions,\n  SdkField,\n  SdkGeofence,\n  SdkPerson,\n  SdkLocation,\n  SdkRow,\n  SdkTable,\n  SdkUser,\n} from './types';\n",
  "src/react.ts": "import { useCallback, useEffect, useRef, useState } from 'react';\nimport { withUpdates } from './bridge';\nimport { cortex } from './cortex';\nimport {\n  EMPTY_OUTBOX,\n  getLiveStatus,\n  getOutbox,\n  isHostVisible,\n  onHostVisible,\n  onLiveStatus,\n  onOutbox,\n} from './events';\nimport type {\n  LiveEvent,\n  LiveOptions,\n  LiveStatus,\n  OutboxItem,\n  OutboxState,\n  QueryOptions,\n  SdkLocation,\n  SdkRow,\n  SdkUser,\n} from './types';\n\n/**\n * Ganchos de React. Los que refrescan solos (`refreshMs`) se pausan mientras la\n * pestaña está oculta y refrescan al volver, para no gastar llamadas (el tope\n * es de 120 por minuto).\n */\n\n/** Con la pestaña a la vista Y con el marco mostrando esta pantalla (los iframes vivos se ocultan). */\nfunction visible(): boolean {\n  return (\n    isHostVisible() && (typeof document === 'undefined' || document.visibilityState !== 'hidden')\n  );\n}\n\n/** Rebote entre el aviso de cambio y la relectura (varias escrituras seguidas = una lectura). */\nexport const LIVE_DEBOUNCE_MS = 300;\n/** Sondeo de respaldo cuando el canal en vivo no está conectado. */\nexport const LIVE_FALLBACK_MS = 30_000;\n\n/** Carga con `load` ahora y cada `refreshMs`, solo con la pantalla visible. */\nfunction useLoader<T>(\n  load: () => Promise<T>,\n  deps: unknown[],\n  refreshMs?: number,\n  liveTables?: string[],\n) {\n  const [data, setData] = useState<T | null>(null);\n  const [loading, setLoading] = useState(true);\n  const [error, setError] = useState<string | null>(null);\n  const loadRef = useRef(load);\n  loadRef.current = load;\n  const alive = useRef(true);\n  const refreshRef = useRef<() => Promise<void>>(async () => undefined);\n\n  const refresh = useCallback(async () => {\n    try {\n      // Las llamadas de `load` piden respuesta en dos tiempos: si el host contestó con lo guardado\n      // y luego llega el dato fresco, se vuelve a cargar (ahora el host ya lo tiene al día).\n      const next = await withUpdates(\n        () => {\n          if (alive.current) void refreshRef.current();\n        },\n        () => loadRef.current(),\n      );\n      if (!alive.current) return;\n      setData(next);\n      setError(null);\n    } catch (e) {\n      if (alive.current) setError(e instanceof Error ? e.message : 'No se pudo cargar.');\n    } finally {\n      if (alive.current) setLoading(false);\n    }\n  }, []);\n  refreshRef.current = refresh;\n\n  const liveKey = liveTables?.length ? [...liveTables].sort().join(',') : '';\n  // Con el canal en vivo conectado no hace falta sondear; sin él, un respaldo cada 30 s.\n  const status = useLiveStatus(Boolean(liveKey));\n  const pollMs = liveKey\n    ? status === 'live'\n      ? 0\n      : Math.min(refreshMs && refreshMs > 0 ? refreshMs : LIVE_FALLBACK_MS, LIVE_FALLBACK_MS)\n    : (refreshMs ?? 0);\n  // Algo cambió mientras la pantalla estaba oculta: se vuelve a leer al mostrarse.\n  const dirty = useRef(false);\n\n  // biome-ignore lint/correctness/useExhaustiveDependencies: `deps` es la lista del llamador.\n  useEffect(() => {\n    alive.current = true;\n    setLoading(true);\n    void refresh();\n    return () => {\n      alive.current = false;\n    };\n  }, [refresh, ...deps]);\n\n  useEffect(() => {\n    const timer =\n      pollMs > 0\n        ? setInterval(() => {\n            if (visible()) void refresh();\n          }, pollMs)\n        : null;\n    const refreshIfVisible = () => {\n      if (!visible()) return;\n      if (pollMs > 0 || dirty.current) {\n        dirty.current = false;\n        void refresh();\n      }\n    };\n    document.addEventListener('visibilitychange', refreshIfVisible);\n    const offVisible = onHostVisible(refreshIfVisible);\n    return () => {\n      if (timer) clearInterval(timer);\n      document.removeEventListener('visibilitychange', refreshIfVisible);\n      offVisible();\n    };\n  }, [refresh, pollMs]);\n\n  useEffect(() => {\n    if (!liveKey) return;\n    let t: ReturnType<typeof setTimeout> | undefined;\n    const off = cortex.live.subscribe(liveKey.split(','), () => {\n      if (t) clearTimeout(t);\n      t = setTimeout(() => {\n        if (!alive.current) return;\n        if (visible()) void refreshRef.current();\n        else dirty.current = true;\n      }, LIVE_DEBOUNCE_MS);\n    });\n    return () => {\n      if (t) clearTimeout(t);\n      off();\n    };\n  }, [liveKey]);\n\n  return { data, loading, error, refresh };\n}\n\n/**\n * Carga lo que devuelva `load` ahora, cuando cambie `deps` y cada `refreshMs` (sondeo: se pausa\n * con la pestaña oculta y refresca al volver). Sirve para combinar varias llamadas del SDK.\n */\nexport function useAsync<T>(\n  load: () => Promise<T>,\n  deps: unknown[] = [],\n  config: { refreshMs?: number } = {},\n): { data: T | null; loading: boolean; error: string | null; refresh: () => Promise<void> } {\n  return useLoader(load, deps, config.refreshMs);\n}\n\n/** Quién usa la pantalla. */\nexport function useUser(): { user: SdkUser | null; loading: boolean; error: string | null } {\n  const { data, loading, error } = useLoader(() => cortex.user.me(), []);\n  return { user: data, loading, error };\n}\n\n/** Filas de una tabla, con refresco opcional. `opts` se compara por valor. */\nexport function useQuery(\n  table: string,\n  opts: QueryOptions = {},\n  config: LiveOptions = {},\n): { rows: SdkRow[]; loading: boolean; error: string | null; refresh: () => Promise<void> } {\n  const key = JSON.stringify(opts);\n  const { data, loading, error, refresh } = useLoader(\n    () => cortex.tables.query(table, opts),\n    [table, key],\n    config.refreshMs,\n    config.live ? [table] : undefined,\n  );\n  return { rows: data?.rows ?? [], loading, error, refresh };\n}\n\n/** Ubicaciones en vivo (solo si el rol puede verlas). */\nexport function useLocations(config: { refreshMs?: number } = {}): {\n  locations: SdkLocation[];\n  loading: boolean;\n  error: string | null;\n  refresh: () => Promise<void>;\n} {\n  const { data, loading, error, refresh } = useLoader(\n    () => cortex.locations.live(),\n    [],\n    config.refreshMs,\n  );\n  return { locations: data ?? [], loading, error, refresh };\n}\n\n/** El estado del canal en vivo (`live` | `reconnecting` | `off`); se repinta cuando cambia. */\nexport function useLiveStatus(enabled = true): LiveStatus {\n  const [status, setStatus] = useState<LiveStatus>(() => getLiveStatus());\n  useEffect(() => {\n    if (!enabled) return;\n    setStatus(getLiveStatus());\n    return onLiveStatus(setStatus);\n  }, [enabled]);\n  return status;\n}\n\n/** Avisa (`cb`) cuando cambia alguna de estas tablas. Sin rebote: úsalo para reaccionar, no para releer. */\nexport function useLive(tables: string[], cb: (ev: LiveEvent) => void): void {\n  const cbRef = useRef(cb);\n  cbRef.current = cb;\n  const key = [...tables].sort().join(',');\n  useEffect(() => {\n    if (!key) return;\n    return cortex.live.subscribe(key.split(','), (ev) => cbRef.current(ev));\n  }, [key]);\n}\n\n/** La cola sin señal: cuántas operaciones esperan, cuáles, cuáles fallaron y cómo reintentar. */\nexport function useOutbox(): {\n  pending: number;\n  items: OutboxItem[];\n  failed: number;\n  online: boolean;\n  retry: () => Promise<void>;\n  discard: (localId: string) => Promise<void>;\n} {\n  const [state, setState] = useState<OutboxState>(() => getOutbox());\n  useEffect(() => {\n    setState(getOutbox());\n    const off = onOutbox(setState);\n    // El host guarda la cola entre pantallas: se le pide la actual al montar.\n    void cortex.outbox.list().then(() => setState(getOutbox()));\n    return off;\n  }, []);\n  const retry = useCallback(() => cortex.outbox.retry(), []);\n  const discard = useCallback((id: string) => cortex.outbox.discard(id), []);\n  const s = state ?? EMPTY_OUTBOX;\n  return { pending: s.pending, items: s.items, failed: s.failed, online: s.online, retry, discard };\n}\n",
  "src/types.ts": "/** Tipos públicos del SDK. Reflejan lo que responde el servidor (`runSdkOp`). */\n\nexport interface SdkUser {\n  id: string;\n  name: string;\n  role: string;\n  attributes: Record<string, string>;\n  /** Referencia de la persona, con el mismo formato que `SdkPerson.ref` («m:…» o «u:…»). */\n  ref: string;\n}\n\n/** Una persona a quien se le puede asignar algo (`cortex.people.list`). */\nexport interface SdkPerson {\n  ref: string;\n  name: string;\n  roleKey: string;\n  roleName: string;\n  onShift: boolean;\n}\n\nexport interface SdkField {\n  key: string;\n  label: string;\n  type: string;\n  options?: string[];\n}\n\nexport interface SdkTable {\n  /** Id o nombre con el que se pide la tabla en `tables.query(...)`. */\n  id: string;\n  name: string;\n  fields: SdkField[];\n}\n\nexport interface SdkRow {\n  id: string;\n  label: string;\n  values: Record<string, unknown>;\n  created_at: string;\n  updated_at: string;\n}\n\nexport interface QueryOptions {\n  /** Igualdad por campo: `{ estado: 'abierta' }`. */\n  where?: Record<string, unknown>;\n  search?: string;\n  order?: { field: string; dir?: 'asc' | 'desc' };\n  /** Máximo 500. */\n  limit?: number;\n  offset?: number;\n}\n\nexport interface SdkLocation {\n  userId: string;\n  name: string;\n  lat: number;\n  lng: number;\n  accuracy?: number | null;\n  at: string;\n}\n\nexport interface SdkGeofence {\n  id: string;\n  name: string;\n  [key: string]: unknown;\n}\n\n/** Un botón de flujo de una tabla que el rol puede correr (`tables.listActions`). */\nexport interface SdkAction {\n  key: string;\n  label: string;\n}\n\nexport interface ActionResult {\n  message: string;\n  /** La fila como quedó, si el rol todavía la ve. */\n  row?: SdkRow;\n}\n\nexport interface UploadOptions {\n  table: string;\n  id: string;\n  /** El campo de tipo archivo de la fila al que se agrega. */\n  field: string;\n  /** Nombre con que se guarda; por omisión el del archivo. */\n  name?: string;\n  /** Sin señal se guarda en el teléfono (el blob incluido) y se sube al volver; contesta `Queued`. */\n  offline?: boolean;\n}\n\nexport interface UploadResult {\n  url: string;\n  name: string;\n  /** Los valores de la fila después de agregar el archivo. */\n  values: Record<string, unknown>;\n}\n\nexport interface PickOptions {\n  /** Atributo `accept` del selector: `image/*`, `application/pdf`… */\n  accept?: string;\n  /** Abre la cámara en vez de la galería (celulares). */\n  capture?: 'environment' | 'user';\n  multiple?: boolean;\n}\n\nexport interface ScanOptions {\n  kind?: 'manifiesto' | 'guia' | 'general';\n  /** Devolver también los renglones (por omisión sí en `manifiesto`). */\n  rows?: boolean;\n}\n\nexport type ScanValue = string | number;\n\nexport interface ScanResult {\n  fields: Record<string, ScanValue>;\n  rows: Record<string, ScanValue>[];\n  text?: string;\n}\n\nexport interface SdkPosition {\n  lat: number;\n  lng: number;\n  accuracy: number;\n  /** El nombre de la zona de la app donde está, o null. */\n  zone: string | null;\n  /** true/false según las zonas de la app; null si la app no tiene zonas. */\n  inside: boolean | null;\n}\n\nexport interface PrintOptions {\n  /** Título del documento (el nombre que propone «guardar como PDF»). */\n  title?: string;\n}\n\nexport interface ConfirmOptions {\n  confirmLabel?: string;\n  /** Pinta el botón principal como acción que no se deshace. */\n  danger?: boolean;\n}\n\n// ---------------------------------------------------------------------------\n// Canal en vivo, cola sin señal\n// ---------------------------------------------------------------------------\n\n/** Estado del canal en vivo de la app: `live` conectado, `reconnecting` reintentando, `off` sin canal (se sondea). */\nexport type LiveStatus = 'live' | 'reconnecting' | 'off';\n\n/** Aviso de que algo cambió en una tabla (el nombre es el mismo con el que se pidió). */\nexport interface LiveEvent {\n  table: string;\n  at: string;\n}\n\n/** Opciones de las escrituras que pueden esperar a que vuelva la señal. */\nexport interface WriteOptions {\n  /**\n   * Sin red (o con un fallo de red/5xx) el marco guarda la operación en el teléfono y contesta\n   * `{ queued: true, localId }`; sale sola, en orden, al volver la señal.\n   */\n  offline?: boolean;\n}\n\n/** Lo que devuelve una escritura `offline` que quedó en la cola. */\nexport interface Queued {\n  queued: true;\n  /** Id local de la operación. Sirve como `id` de filas creadas sin señal y para `outbox.discard`. */\n  localId: string;\n  /** Referencia local (`local:<localId>`): se puede usar como valor o como `id` en operaciones encoladas después. */\n  ref: string;\n}\n\n/** Lo que una escritura devuelve según se pida `offline` o no. */\nexport type MaybeQueued<T, O extends WriteOptions | undefined> = O extends { offline: true }\n  ? T | Queued\n  : T;\n\nexport interface OutboxItem {\n  id: string;\n  /** La operación: `tables.insert`, `tables.update`, `tables.action`, `files.upload`. */\n  op: string;\n  table: string;\n  label: string;\n  /** `pending` por enviar · `retrying` falló y se reintenta · `rejected` el servidor dijo que no (espera a la persona). */\n  state: 'pending' | 'retrying' | 'rejected';\n  attempts: number;\n  createdAt: number;\n  error?: string;\n}\n\nexport interface OutboxState {\n  items: OutboxItem[];\n  /** Los que saldrán solos. */\n  pending: number;\n  /** Los rechazados. */\n  failed: number;\n  /** El teléfono tiene señal. */\n  online: boolean;\n}\n\nexport interface LiveOptions {\n  /** Cuando cambia la tabla se vuelve a leer (con rebote de ~300 ms). */\n  live?: boolean;\n  /** Sondeo explícito en ms; con `live` solo se usa si el canal no está conectado. */\n  refreshMs?: number;\n}\n"
};
